WITH recent_employees AS (SELECT * FROM employees WHERE manager_id IS NOT NULL AND email LIKE '%@gmail.com' AND LOWER(TRIM(email)) = 'bob.smith@yahoo.com'), employees_stats AS (SELECT level, SUM(CASE WHEN job_title = 'Manager' THEN salary ELSE 0 END) AS manager_salary, MAX(salary) AS max_salary FROM recent_employees GROUP BY level) SELECT level, manager_salary, max_salary FROM employees_stats WHERE max_salary > 148000 ORDER BY 2 DESC, max_salary, level LIMIT 3
